 for(let i=0;i<48;i++)if(t.type==='tou'&&inWindow(i*30,t.start,t.end))svg+=`<rect x="${pad+i*bw}" y="12" width="${bw+.1}" height="${chartH}" fill="#eaf1fe"/>`;
 for(let n=0;n<4;n++){const y=12+chartH*n/3;svg+=`<line x1="${pad}" y1="${y}" x2="${width-pad}" y2="${y}" stroke="#dfe7ef" stroke-dasharray="3 4"/>`;}
 for(let i=0;i<48;i++){const h=home[i]/max*chartH,e=ev[i]/max*chartH,x=pad+i*bw+2,y=12+chartH-h;svg+=`<rect x="${x}" y="${y}" width="${bw-4}" height="${h}" rx="2" fill="#2860cc"><title>${clock(i*30)} home: ${home[i].toFixed(3)} kWh</title></rect><rect x="${x}" y="${y-e}" width="${bw-4}" height="${e}" rx="2" fill="#167c80"><title>${clock(i*30)} car: ${ev[i].toFixed(3)} kWh</title></rect>`;}
