 $('metrics').innerHTML=`<div class="metric"><p>EDF benchmark</p><strong>${money(baseline.active.total)}</strong><span>${suffix} at the selected rates</span></div><div class="metric"><p>Lowest modelled cost</p><strong>${money(best.active.total)}</strong><span>${esc(best.name)}</span></div><div class="metric saving"><p>Potential saving</p><strong>${money(Math.max(0,best.saving))}</strong><span>${isActual&&stats.missing?'Incomplete data: treat with caution':suffix+' under this scenario'}</span></div>`;
